tasks.command:
$root = git rev-parse --show-toplevel
if (($LASTEXITCODE -ne 0) -or ((Resolve-Path $root).Path -ne $PWD.Path)) { throw 'Execute a tarefa na raiz do repositorio FitG.' }
$origin = git remote get-url origin
if ($origin -ne 'https://github.com/Luiz-Gustavo-Santos/FitG.git') { throw 'Repositorio remoto inesperado.' }
$branch = git branch --show-current
if ($branch -ne 'main') { throw 'Esta tarefa envia somente a branch main.' }
$null = git rev-parse --verify --quiet HEAD
if ($LASTEXITCODE -ne 0) {
  git add -- .
  if ($LASTEXITCODE -ne 0) { throw 'Falha ao preparar a base inicial.' }
  $excluded = git ls-files --cached -- .env '.env.*' node_modules dist coverage artifacts playwright-report
  if ($excluded) { throw 'Arquivos locais indevidos no indice; envio interrompido.' }
  git commit -m 'chore: versionar base inicial do FitG 0.1.0'
  if ($LASTEXITCODE -ne 0) { throw 'Falha ao criar o commit inicial.' }
}
git -c credential.interactive=false push --set-upstream origin main
if ($LASTEXITCODE -ne 0) { throw 'Falha ao enviar commits ao GitHub.' }
$local = git rev-parse HEAD
$remote = git -c credential.interactive=false ls-remote origin refs/heads/main
if (($LASTEXITCODE -ne 0) -or (($remote -split '\s+')[0] -ne $local.Trim())) { throw 'Nao foi possivel confirmar a sincronizacao.' }
git --no-pager log -1 --format='%h %s'
git --no-pager status --short --branch
